/*
id: profile_credits
title: [tidal export] Profile Credits
athena_id: cd7ed02c-1ede-4c77-b74c-a49986a8f156
primary_tag: tidal-export
tags: [tidal-export]
athena_database: platform-industry-db-industry-prod
description: No description provided
status: experimental
pii: unknown
last_exported: 2025-01-31
*/

with p AS (
	select p._id AS profile_id,
		"profile_type" AS type,
		name,
		array_join(
			filter(
				TRANSFORM(
					"common_credits",
					c->case
						when lower(c) LIKE '%organi%' then 'Organization'
						when lower(c) LIKE '%producer%' then 'Producer' else c
					end
				),
				c->c is not null
				and c <> 'Other'
			),
			', '
		) AS common_credits,
		"collaborations_count" AS num_collaborators,
		greatest(
			COALESCE("credits_count", 1),
			COALESCE("tracks_count", 1)
		) AS num_credits
	FROM hive."platform-industry-bi-prod"."matvw_catalog_profile" AS p
	where _id in (
			'e32ace23-880c-49f0-8db9-836492c6610e',
