select distinct profile_id,
	t._id AS track_id,
	t.title AS track_title,
	case
		when lower(credit.parent) LIKE '%organi%' then 'Organization'
		when lower(credit.parent) LIKE '%producer%' then 'Producer' else credit.parent
	end,
	credit.child,
	credit.classification,
	credit.instrument_family
from hive."platform-industry-bi-prod"."matvw_catalog_master_credit" AS c
	join p USING(profile_id)
	join hive."platform-industry-bi-prod"."matvw_catalog_track" AS t ON (t._id = c.master_track_id)
	cross join unnest("catalog_credits") AS cc(credit)
where lower(credit.parent) not in ('other')
limit 10000